import FreeCAD

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Check the existing features
print("=== Existing Features ===")
pad = doc.getObject("Pad")
if pad:
    print(f"Pad:")
    print(f"  TypeId: {pad.TypeId}")
    print(f"  Length: {pad.Length}")
    print(f"  Base Feature: {pad.BaseFeature}")
    # List all properties
    for prop in dir(pad):
        if not prop.startswith('_'):
            try:
                val = getattr(pad, prop)
                if not callable(val):
                    print(f"  {prop}: {val}")
            except:
                pass

pocket = doc.getObject("Pocket")
if pocket:
    print(f"\nPocket:")
    print(f"  TypeId: {pocket.TypeId}")
    for prop in dir(pocket):
        if not prop.startswith('_'):
            try:
                val = getattr(pocket, prop)
                if not callable(val):
                    print(f"  {prop}: {val}")
            except:
                pass

# Check Body
body = doc.getObject("Body")
if body:
    print(f"\nBody:")
    print(f"  Shape: {body.Shape}")
    print(f"  Volume: {body.Shape.Volume if body.Shape else 'N/A'}")

FreeCAD.closeDocument(doc.Name)
EOF"}

